def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    op = [h[1] for h in history]
    me = [h[0] for h in history]
    last = op[-1]
    op_c = op.count('C')
    op_d = n - op_c

    # Detect pure/sustained defection: never reward it
    if op_d == n:
        return 'D'

    # Detect pure cooperation: gently exploit near the end only
    if op_c == n:
        if n >= 96:
            return 'D'
        return 'C'

    # Streak lengths at end
    run = 0
    for i in range(n - 1, -1, -1):
        if op[i] == last:
            run += 1
        else:
            break

    # If opponent has been defecting heavily overall, defect
    if op_d * 3 >= n * 2:
        if last == 'C' and run >= 3:
            return 'C'
        return 'D'

    # Handle opponent defection with graduated retaliation
    if last == 'D':
        if run == 1:
            # Single defection: retaliate once, but forgive if they were fine before
            if op_d * 4 <= n and me[-1] == 'D':
                return 'C'
            return 'D'
        if run == 2:
            return 'D'
        # long D streak: break out occasionally to test for forgiveness
        if run >= 4 and op_c * 2 >= n:
            return 'C' if rng.random() < 0.2 else 'D'
        return 'D'

    # Opponent just cooperated
    if n >= 97:
        return 'D'
    # If opponent is mostly cooperative, cooperate but occasionally probe late
    if op_d * 5 <= n:
        if n >= 90 and rng.random() < 0.3:
            return 'D'
        return 'C'
    # Mixed opponent: copy last, with light forgiveness to escape D-D loops
    if run >= 1:
        # they cooperated now; if we were in D-D, cooperate to restore
        if me[-1] == 'D' and n >= 2 and op[-2] == 'D':
            return 'C'
        return 'C'
    return 'C'
